const pocket = data && data.target && Array.isArray(data.target.pocket_atoms) ? data.target.pocket_atoms : [];
const best = data && data.best_candidate ? data.best_candidate : null;
const searchCandidates = data && Array.isArray(data.search_candidates) ? data.search_candidates : [];
const validation = data && data.reference_pose_validation ? data.reference_pose_validation : null;

