const canvas = root.querySelector("canvas");
const ctx = canvas.getContext("2d");
const titleNode = root.querySelector(".title");
const subNode = root.querySelector(".sub");
const candidateNode = root.querySelector(".candidate-id");
const legendNode = root.querySelector(".legend");
const sceneDots = Array.from(root.querySelectorAll(".scene-dot"));

let width = 1;
let height = 1;

const SCENE_TARGET_MS = 4200;
const SCENE_SEARCH_MS = 6000;
const SCENE_RESULT_MS = 6200;
const SCENE_TOTAL_MS = SCENE_TARGET_MS + SCENE_SEARCH_MS + SCENE_RESULT_MS;
const TRANSITION_MS = 600;

function resize(){
  const rect = canvas.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const w = Math.max(1, Math.round(rect.width * dpr));
  const h = Math.max(1, Math.round(rect.height * dpr));
  if(canvas.width !== w || canvas.height !== h){
    canvas.width = w;
    canvas.height = h;
    width = w;
    height = h;
  }
  return dpr;
}

function clamp01(value){ return Math.max(0, Math.min(1, value)); }
function smooth(value){ const t=clamp01(value); return t*t*(3-2*t); }
function fadeWindow(local, duration){
  const fadeIn = smooth(local / TRANSITION_MS);
  const fadeOut = smooth((duration - local) / TRANSITION_MS);
  return Math.min(fadeIn, fadeOut);
}

function centroid(atoms){
  if(!atoms || !atoms.length) return [26.7, 6.1, 4.2];
  let x=0,y=0,z=0;
  atoms.forEach(atom=>{x+=atom.position[0];y+=atom.position[1];z+=atom.position[2];});
  return [x/atoms.length,y/atoms.length,z/atoms.length];
}

const referenceAtoms = validation && Array.isArray(validation.crystal_atoms) ? validation.crystal_atoms : [];
const bestAtoms = best && Array.isArray(best.atoms) ? best.atoms : [];
const targetCenter = centroid(referenceAtoms.length ? referenceAtoms : (bestAtoms.length ? bestAtoms : pocket));

function rotate(point, center, yaw){
  let x=point[0]-center[0], y=point[1]-center[1], z=point[2]-center[2];
  const ca=Math.cos(yaw), sa=Math.sin(yaw), cb=Math.cos(-0.32), sb=Math.sin(-0.32);
  const x1=x*ca-z*sa, z1=x*sa+z*ca;
  const y2=y*cb-z1*sb, z2=y*sb+z1*cb;
  return [x1,y2,z2];
}

function project(point){
  const scale = Math.min(width,height)*0.060;
  const perspective = 1/(1+Math.max(-8,Math.min(8,point[2]))*0.025);
  return [width*0.52+point[0]*scale*perspective,height*0.54-point[1]*scale*perspective,point[2],perspective];
}

function atomDistance(a,b){
  return Math.hypot(a.position[0]-b.position[0],a.position[1]-b.position[1],a.position[2]-b.position[2]);
}

function pointDistance(a,b){ return Math.hypot(a[0]-b[0],a[1]-b[1]); }

function distanceToCenter(atom, center){
  return Math.hypot(atom.position[0]-center[0],atom.position[1]-center[1],atom.position[2]-center[2]);
}

function distanceToAtoms(atom, atoms){
  let value=Infinity;
  atoms.forEach(other=>{ value=Math.min(value, atomDistance(atom,other)); });
  return value;
}

function bondPairs(atoms,maxDistance){
  const pairs=[];
  for(let i=0;i<atoms.length;i++) for(let j=i+1;j<atoms.length;j++){
    if(atomDistance(atoms[i],atoms[j])<maxDistance) pairs.push([i,j]);
  }
  return pairs;
}

function contactPairs(pocketAtoms, ligandAtoms, maxDistance){
  const pairs=[];
  for(let li=0;li<ligandAtoms.length;li++){
    const candidates=[];
    for(let pi=0;pi<pocketAtoms.length;pi++){
      const d=atomDistance(ligandAtoms[li],pocketAtoms[pi]);
      if(d<=maxDistance) candidates.push({pi,d});
    }
    candidates.sort((a,b)=>a.d-b.d);
    candidates.slice(0,2).forEach(item=>pairs.push([item.pi,li,item.d]));
  }
  return pairs;
}

function localPocketAtoms(center, count){
  return pocket
    .map((atom,index)=>({atom,index,distance:distanceToCenter(atom,center)}))
    .sort((a,b)=>a.distance-b.distance)
    .slice(0,Math.min(count,pocket.length));
}

const localPocket = localPocketAtoms(targetCenter, 26);

function convexHull(points){
  if(points.length<3) return points.slice();
  const sorted=points.slice().sort((a,b)=>a[0]===b[0]?a[1]-b[1]:a[0]-b[0]);
  const cross=(o,a,b)=>(a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0]);
  const lower=[];
  sorted.forEach(p=>{while(lower.length>=2 && cross(lower[lower.length-2],lower[lower.length-1],p)<=0) lower.pop();lower.push(p);});
  const upper=[];
  [...sorted].reverse().forEach(p=>{while(upper.length>=2 && cross(upper[upper.length-2],upper[upper.length-1],p)<=0) upper.pop();upper.push(p);});
  lower.pop();upper.pop();
  return lower.concat(upper);
}

function expandedHull(points, padding){
  if(!points.length) return [];
  const center=[points.reduce((sum,p)=>sum+p[0],0)/points.length,points.reduce((sum,p)=>sum+p[1],0)/points.length];
  return convexHull(points).map(p=>{
    const dx=p[0]-center[0],dy=p[1]-center[1],length=Math.max(1,Math.hypot(dx,dy));
    return [p[0]+dx/length*padding,p[1]+dy/length*padding];
  });
}

function drawClosedShape(points, fill, stroke, lineWidth, dash){
  if(points.length<3) return;
  ctx.save();
  if(dash) ctx.setLineDash(dash);
  ctx.beginPath();
  points.forEach((p,index)=>{if(index===0)ctx.moveTo(p[0],p[1]);else ctx.lineTo(p[0],p[1]);});
  ctx.closePath();
  if(fill){ctx.fillStyle=fill;ctx.fill();}
  if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=lineWidth;ctx.stroke();}
  ctx.restore();
}

function proteinBodyPoints(){
  const cx=width*0.52, cy=height*0.55;
  const rx=Math.min(width,height)*0.34;
  const ry=Math.min(width,height)*0.30;
  const factors=[1.00,0.92,1.06,0.90,1.02,0.94,1.07,0.91,1.03,0.95,1.04,0.90,1.05,0.93];
  const points=[];
  for(let i=0;i<factors.length;i++){
    const angle=(Math.PI*2*i/factors.length)-0.22;
    const f=factors[i];
    points.push([cx+Math.cos(angle)*rx*f,cy+Math.sin(angle)*ry*f]);
  }
  return points;
}

function drawProteinBody(alpha,dpr){
  drawClosedShape(proteinBodyPoints(),`rgba(242,242,244,${0.92*alpha})`,`rgba(199,199,204,${0.95*alpha})`,1.25*dpr,null);
}

function drawInternalPocketLabel(projectedLocal,alpha,dpr){
  if(!projectedLocal.length) return;
  const x=projectedLocal.reduce((sum,p)=>sum+p[0],0)/projectedLocal.length;
  const y=projectedLocal.reduce((sum,p)=>sum+p[1],0)/projectedLocal.length;
  ctx.save();
  ctx.globalAlpha=alpha;
  ctx.fillStyle="#6e6e73";
  ctx.font=`${10*dpr}px -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif`;
  ctx.textAlign="center";
  ctx.fillText("internal pocket",x,y+4*dpr);
  ctx.restore();
}

function drawPocketBoundary(projectedLocal, alpha, dpr){
  const points=projectedLocal.map(item=>[item[0],item[1]]);
  const hull=expandedHull(points,12*dpr);
  drawClosedShape(hull,`rgba(0,0,0,${0.018*alpha})`,`rgba(29,29,31,${0.22*alpha})`,1.15*dpr,[5*dpr,5*dpr]);
}

function drawPocketAtoms(projectedPocket, ligandAtoms, alpha, dpr, contactIndexes){
  const items=pocket.map((atom,index)=>({atom,index,p:projectedPocket[index],distance:ligandAtoms.length?distanceToAtoms(atom,ligandAtoms):distanceToCenter(atom,targetCenter)}));
  items.sort((a,b)=>a.p[2]-b.p[2]);
  items.forEach(item=>{
    const contact=contactIndexes && contactIndexes.has(item.index);
    const near=item.distance<=6.2;
    if(!near && !contact) return;
    const radius=(contact?5.3:(near?3.7:2.7))*dpr*item.p[3];
    ctx.beginPath();ctx.arc(item.p[0],item.p[1],radius,0,Math.PI*2);
    ctx.fillStyle=contact?`rgba(255,255,255,${0.98*alpha})`:`rgba(229,229,231,${0.82*alpha})`;
    ctx.fill();
    ctx.strokeStyle=contact?`rgba(29,29,31,${0.62*alpha})`:`rgba(134,134,139,${0.32*alpha})`;
    ctx.lineWidth=(contact?1.15:0.8)*dpr;
    ctx.stroke();
  });
}

function drawBonds(projected,pairs,stroke,widthPx,alpha){
  if(!pairs.length) return;
  ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle=stroke;ctx.lineWidth=widthPx;ctx.beginPath();
  pairs.forEach(pair=>{const a=projected[pair[0]],b=projected[pair[1]];ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);});
  ctx.stroke();ctx.restore();
}

function drawMolecule(atoms, projected, alpha, dpr, offsetX){
  if(!atoms.length) return;
  const bonds=bondPairs(atoms,1.82);
  const moved=projected.map(p=>[p[0]+offsetX,p[1],p[2],p[3]]);
  drawBonds(moved,bonds,"#1d1d1f",2.0*dpr,alpha);
  const sorted=atoms.map((atom,index)=>({atom,p:moved[index]})).sort((a,b)=>a.p[2]-b.p[2]);
  sorted.forEach(item=>{
    const radius=4.8*dpr*item.p[3];
    ctx.save();ctx.globalAlpha=alpha;
    ctx.beginPath();ctx.arc(item.p[0],item.p[1],radius,0,Math.PI*2);
    ctx.fillStyle="#1d1d1f";ctx.fill();
    ctx.beginPath();ctx.arc(item.p[0]-radius*.25,item.p[1]-radius*.3,radius*.22,0,Math.PI*2);
    ctx.fillStyle="#ffffff";ctx.globalAlpha=alpha*.72;ctx.fill();ctx.restore();
  });
}

function drawReference(projected, alpha, dpr){
  if(!referenceAtoms.length) return;
  const bonds=bondPairs(referenceAtoms,1.82);
  ctx.save();ctx.setLineDash([5*dpr,4*dpr]);
  drawBonds(projected,bonds,"#86868b",1.25*dpr,alpha*.72);
  ctx.restore();
  projected.forEach(p=>{
    ctx.save();ctx.globalAlpha=alpha*.78;ctx.beginPath();ctx.arc(p[0],p[1],4.6*dpr*p[3],0,Math.PI*2);ctx.strokeStyle="#86868b";ctx.lineWidth=1.1*dpr;ctx.stroke();ctx.restore();
  });
}

function drawContacts(projectedPocket, projectedLigand, contacts, alpha, dpr){
  if(!contacts.length) return;
  ctx.save();ctx.globalAlpha=alpha;ctx.strokeStyle="#86868b";ctx.lineWidth=1*dpr;ctx.setLineDash([4*dpr,5*dpr]);
  contacts.forEach(pair=>{
    const p=projectedPocket[pair[0]],l=projectedLigand[pair[1]];
    ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(l[0],l[1]);ctx.stroke();
  });
  ctx.restore();
}

function setStory(scene, title, sub, candidate, legend){
  titleNode.textContent=title;
  subNode.textContent=sub;
  candidateNode.textContent=candidate || "";
  legendNode.innerHTML=legend || "";
  sceneDots.forEach((dot,index)=>dot.classList.toggle("active",index===scene));
}

function targetLegend(){
  return '<span><i class="mark protein"></i>protein body (schematic)</span><span><i class="mark pocket"></i>measured pocket</span>';
}
function searchLegend(){
  return '<span><i class="mark pocket"></i>measured pocket</span><span><i class="mark candidate"></i>candidate</span>';
}
function resultLegend(){
  return `<span><i class="mark pocket"></i>pocket contacts</span><span><i class="mark contact"></i>predicted contacts</span><span><i class="mark candidate"></i>candidate</span>${referenceAtoms.length?'<span><i class="mark reference"></i>181L reference</span>':''}`;
}

function frame(now){
  const dpr=resize();
  ctx.clearRect(0,0,width,height);
  ctx.fillStyle="#ffffff";ctx.fillRect(0,0,width,height);

  const cycle=now%SCENE_TOTAL_MS;
  let scene=0, local=cycle, duration=SCENE_TARGET_MS;
  if(cycle>=SCENE_TARGET_MS && cycle<SCENE_TARGET_MS+SCENE_SEARCH_MS){scene=1;local=cycle-SCENE_TARGET_MS;duration=SCENE_SEARCH_MS;}
  else if(cycle>=SCENE_TARGET_MS+SCENE_SEARCH_MS){scene=2;local=cycle-SCENE_TARGET_MS-SCENE_SEARCH_MS;duration=SCENE_RESULT_MS;}
  const alpha=fadeWindow(local,duration);
  const yaw=now*0.00011;

  const rotatedPocket=pocket.map(atom=>rotate(atom.position,targetCenter,yaw));
  const projectedPocket=rotatedPocket.map(project);
  const projectedLocal=localPocket.map(item=>projectedPocket[item.index]);

  if(scene===0){
    setStory(0,"1. The target pocket","The protein surrounds a small internal cavity. ProteinLock asks which molecule fits best inside this measured pocket.","",targetLegend());
    drawProteinBody(alpha,dpr);
    drawPocketBoundary(projectedLocal,alpha*1.15,dpr);
    drawPocketAtoms(projectedPocket,[],alpha,dpr,null);
    drawInternalPocketLabel(projectedLocal,alpha,dpr);
    return requestAnimationFrame(frame);
  }

  if(scene===1){
    const candidates=searchCandidates.length?searchCandidates:(best?[best]:[]);
    const count=Math.max(1,candidates.length);
    const slot=SCENE_SEARCH_MS/count;
    const index=Math.min(count-1,Math.floor(local/slot));
    const candidate=candidates[index] || best;
    const slotLocal=local-index*slot;
    const enter=smooth(slotLocal/Math.min(650,slot*.35));
    const leave=smooth((slot-slotLocal)/Math.min(650,slot*.35));
    const candidateAlpha=alpha*Math.min(enter,leave);
    const offsetX=(1-enter)*(-width*0.22);
    const atoms=candidate && Array.isArray(candidate.atoms)?candidate.atoms:[];
    const projected=atoms.map(atom=>project(rotate(atom.position,targetCenter,yaw)));
    setStory(1,"2. Testing candidates","Each real candidate is moved and rotated inside the pocket. ProteinLock scores the fit and keeps the best result.",candidate?candidate.name:"",searchLegend());
    drawPocketBoundary(projectedLocal,alpha,dpr);
    drawPocketAtoms(projectedPocket,atoms,alpha*.72,dpr,null);
    drawMolecule(atoms,projected,candidateAlpha,dpr,offsetX);
    return requestAnimationFrame(frame);
  }

  const atoms=bestAtoms;
  const projectedBest=atoms.map(atom=>project(rotate(atom.position,targetCenter,yaw)));
  const projectedReference=referenceAtoms.map(atom=>project(rotate(atom.position,targetCenter,yaw)));
  const contacts=contactPairs(pocket,atoms,4.2);
  const contactIndexes=new Set(contacts.map(pair=>pair[0]));
  setStory(2,"3. Best predicted fit","The winner sits inside the pocket. Dashed lines mark the non-covalent contacts that contributed to our simplified score.",best?best.name:"",resultLegend());
  drawPocketBoundary(projectedLocal,alpha,dpr);
  drawPocketAtoms(projectedPocket,atoms,alpha,dpr,contactIndexes);
  drawContacts(projectedPocket,projectedBest,contacts,alpha*.88,dpr);
  drawReference(projectedReference,alpha*.62,dpr);
  drawMolecule(atoms,projectedBest,alpha,dpr,0);
  requestAnimationFrame(frame);
}

requestAnimationFrame(frame);
